//! Links to share µcad code in the web viewer, which contain the code.
//!
//! The code is lexed and its tokens are serialized behind an [`ArtifactHeader`] of the kind
//! [`ArtifactKind::Tokens`]: each token as the Huffman code of its kind, the text of a token,
//! e.g. of an identifier, as the Huffman codes of its characters and of the end of the text.
//! The tables are generated by `cargo xtask share-tables` from the tokens of µcad files.

mod bits;
mod tables;

use std::borrow::Cow;
use std::collections::HashMap;
use std::sync::LazyLock;

use base64::{
    Engine,
    alphabet::URL_SAFE,
    engine::{
        DecodePaddingMode, GeneralPurpose, GeneralPurposeConfig, general_purpose::URL_SAFE_NO_PAD,
    },
};
use mucad_lang_base::{ArtifactHeader, ArtifactKind};
use mucad_lang_parse::token::Token;

use bits::{BitReader, BitWriter};

/// The web viewer, which shows the code of a link in its fragment.
///
/// The fragment is not sent to the server, so the web viewer can be a static page, and the code
/// is not logged by the server.
pub const PLAY_URL: &str = "https://play.mucad.org/#";

/// The maximum size of the code in a link, in bytes of its UTF-8 encoding.
pub const MAX_CODE_BYTES: usize = 2048;

/// The maximum size of serialized code, see [`serialize`].
///
/// A byte of code has at most 7 bytes: a token of an unknown kind with a character, which is
/// not in the table, has about 52 bits.
const MAX_SERIALIZED_BYTES: usize = ArtifactHeader::SIZE + 7 * MAX_CODE_BYTES;

/// The number of bits of the code point of a character, which is not in the table.
const CODE_POINT_BITS: u8 = 21;

/// An error of sharing code.
#[derive(Debug, Clone, PartialEq, thiserror::Error)]
pub enum ShareError {
    /// The code is too long for a link.
    #[error("the code has {0} bytes, a link can contain at most {MAX_CODE_BYTES} bytes")]
    TooLong(usize),
    /// The tokens of the code cannot be serialized, so they are lexed again.
    #[error("the code cannot be shared, its tokens change when they are written again")]
    Unsupported,
    /// The link contains no valid base64.
    #[error("the link contains no valid code: {0}")]
    InvalidBase64(String),
    /// The link contains no valid serialized code.
    #[error("the link contains no valid code: {0}")]
    InvalidData(String),
}

/// A token of shared code: its kind and its text in the source code.
#[derive(Debug, Clone, PartialEq)]
pub struct SharedToken {
    /// The kind of the token, e.g. `Identifier`, `Keyword(Fn)` or `SigilColon`.
    pub kind: String,
    /// The text of the token in the source code, e.g. `fn`.
    pub text: String,
    /// If all tokens of the kind have the same text, e.g. `fn`, which is not serialized.
    pub fixed: bool,
}

/// The tokens of the µcad `code` for sharing.
///
/// Their texts are the code again, except that whitespace in multi-line comments and the
/// escapes of literal strings may differ, which does not change the tokens.
pub fn shared_tokens(code: &str) -> Vec<SharedToken> {
    let mut tokens = Vec::new();
    let mut previous: Option<Token> = None;
    for token in mucad_lang_parse::lex(code) {
        let (text, fixed) = match token_text(&token, previous.as_ref()) {
            Some(text) => (text.into_owned(), false),
            None => match fixed_text(&token) {
                Some(text) => (text.to_string(), true),
                // The text of a lexer error is the erroneous code.
                None => (
                    code.get(token.span.clone()).unwrap_or_default().to_string(),
                    false,
                ),
            },
        };
        tokens.push(SharedToken {
            kind: token_kind(&token),
            text,
            fixed,
        });
        previous = Some(token.value);
    }
    tokens
}

/// The kind of a token, the name of its variant, with the keyword or boolean,
/// e.g. `Identifier`, `Keyword(Fn)` or `LiteralBool(true)`.
fn token_kind(token: &Token) -> String {
    let name = format!("{token:?}");
    match token {
        Token::Keyword(_) | Token::LiteralBool(_) => name,
        _ => match name.split_once('(') {
            Some((variant, _)) => variant.to_string(),
            None => name,
        },
    }
}

/// The text of a token with a variable text in the source code, e.g. of an identifier.
///
/// The format of a format string starts with `:`, which is no token, so the first format
/// token after the `previous` token contains it.
fn token_text<'a>(token: &'a Token, previous: Option<&Token>) -> Option<Cow<'a, str>> {
    let is_format = |token: &Token| {
        matches!(
            token,
            Token::StringFormatPrecision(_) | Token::StringFormatWidth(_)
        )
    };
    Some(match token {
        Token::Whitespace(text)
        | Token::SingleLineComment(text)
        | Token::DocComment(text)
        | Token::InnerDocComment(text)
        | Token::Identifier(text)
        | Token::Unit(text)
        | Token::LiteralInt(text)
        | Token::LiteralFloat(text)
        | Token::StringContent(text) => Cow::Borrowed(text),
        Token::StringFormatPrecision(text) | Token::StringFormatWidth(text) => {
            match previous.is_some_and(is_format) {
                true => Cow::Borrowed(text),
                false => format!(":{text}").into(),
            }
        }
        // The comment is lexed without `/*`, `*/` and whitespace.
        Token::MultiLineComment(text) => format!("/* {text} */").into(),
        Token::LiteralString(text) => {
            let mut literal = String::from('"');
            for c in text.chars() {
                match c {
                    '"' | '\\' => literal.extend(['\\', c]),
                    '{' | '}' => literal.extend([c, c]),
                    c => literal.push(c),
                }
            }
            literal.push('"');
            literal.into()
        }
        // An escaped character is lexed without `\`, e.g. `n` for `\n`.
        Token::Character(c) => match c {
            '{' | '}' => format!("{c}{c}").into(),
            c => format!("\\{c}").into(),
        },
        _ => return None,
    })
}

/// The text of a token, which always has the same text, e.g. `fn`.
fn fixed_text(token: &Token) -> Option<&'static str> {
    Some(match token {
        Token::Keyword(keyword) => keyword.as_str(),
        Token::LiteralBool(true) => "true",
        Token::LiteralBool(false) => "false",
        Token::FormatStringStart | Token::FormatStringEnd | Token::SigilQuote => "\"",
        Token::StringFormatOpen => "{",
        Token::StringFormatClose => "}",
        Token::SigilColon => ":",
        Token::SigilSemiColon => ";",
        Token::SigilDoubleColon => "::",
        Token::SigilOpenBracket => "(",
        Token::SigilCloseBracket => ")",
        Token::SigilOpenSquareBracket => "[",
        Token::SigilCloseSquareBracket => "]",
        Token::SigilOpenCurlyBracket => "{",
        Token::SigilCloseCurlyBracket => "}",
        Token::SigilHash => "#",
        Token::SigilDot => ".",
        Token::SigilComma => ",",
        Token::SigilDoubleDot => "..",
        Token::SigilAt => "@",
        Token::SigilSingleArrow => "->",
        Token::OperatorAdd => "+",
        Token::OperatorSubtract => "-",
        Token::OperatorMultiply => "*",
        Token::OperatorDivide => "/",
        Token::OperatorUnion => "|",
        Token::OperatorIntersect => "&",
        Token::OperatorPowerXor => "^",
        Token::OperatorGreaterThan => ">",
        Token::OperatorLessThan => "<",
        Token::OperatorGreaterEqual => ">=",
        Token::OperatorLessEqual => "<=",
        Token::OperatorNear => "~",
        Token::OperatorEqual => "==",
        Token::OperatorNotEqual => "!=",
        Token::OperatorAnd => "and",
        Token::OperatorOr => "or",
        Token::OperatorXor => "xor",
        Token::OperatorNot => "!",
        Token::OperatorAssignment => "=",
        _ => return None,
    })
}

/// A symbol of the token table.
#[derive(Clone, Copy)]
enum TokenSymbol {
    /// A token of a kind in the table, with its text, if it is fixed.
    Kind(Option<&'static str>),
    /// A token of another kind, followed by its text.
    Other,
}

/// A symbol of the character table.
#[derive(Clone, Copy)]
enum TextSymbol {
    Char(char),
    End,
    /// A character, which is not in the table, followed by its code point.
    Other,
}

/// The codes of the token kinds, by their kinds.
static TOKEN_CODES: LazyLock<HashMap<&str, (u32, u8)>> = LazyLock::new(|| {
    tables::TOKENS
        .iter()
        .map(|(kind, _, code, bits)| (*kind, (*code, *bits)))
        .collect()
});

/// The token symbols, by their codes.
static TOKEN_SYMBOLS: LazyLock<HashMap<(u32, u8), TokenSymbol>> = LazyLock::new(|| {
    tables::TOKENS
        .iter()
        .map(|(_, text, code, bits)| ((*code, *bits), TokenSymbol::Kind(*text)))
        .chain([(tables::TOKEN_OTHER, TokenSymbol::Other)])
        .collect()
});

/// The codes of the characters.
static CHAR_CODES: LazyLock<HashMap<char, (u32, u8)>> = LazyLock::new(|| {
    tables::CHARS
        .iter()
        .map(|(c, code, bits)| (*c, (*code, *bits)))
        .collect()
});

/// The character symbols, by their codes.
static TEXT_SYMBOLS: LazyLock<HashMap<(u32, u8), TextSymbol>> = LazyLock::new(|| {
    tables::CHARS
        .iter()
        .map(|(c, code, bits)| ((*code, *bits), TextSymbol::Char(*c)))
        .chain([
            (tables::TEXT_END, TextSymbol::End),
            (tables::TEXT_OTHER, TextSymbol::Other),
        ])
        .collect()
});

/// Write `text` and the end of the text.
fn write_text(writer: &mut BitWriter, text: &str) {
    for c in text.chars() {
        match CHAR_CODES.get(&c) {
            Some((code, bits)) => writer.write(*code, *bits),
            None => {
                writer.write(tables::TEXT_OTHER.0, tables::TEXT_OTHER.1);
                writer.write(c as u32, CODE_POINT_BITS);
            }
        }
    }
    writer.write(tables::TEXT_END.0, tables::TEXT_END.1);
}

/// Serialize the tokens of the µcad `code` behind an artifact header, see the [module](self).
///
/// Fails, if the code has more than [`MAX_CODE_BYTES`] bytes or if its tokens cannot be
/// serialized.
pub fn serialize(code: &str) -> Result<Vec<u8>, ShareError> {
    if code.len() > MAX_CODE_BYTES {
        return Err(ShareError::TooLong(code.len()));
    }
    let tokens = shared_tokens(code);

    // The deserialized code must have the same tokens.
    let text: String = tokens.iter().map(|token| token.text.as_str()).collect();
    let values = |code| mucad_lang_parse::lex(code).map(|token| token.value);
    if !values(code).eq(values(&text)) {
        return Err(ShareError::Unsupported);
    }

    let mut writer = BitWriter::default();
    for token in &tokens {
        match TOKEN_CODES.get(token.kind.as_str()) {
            Some((code, bits)) => {
                writer.write(*code, *bits);
                if !token.fixed {
                    write_text(&mut writer, &token.text);
                }
            }
            None => {
                writer.write(tables::TOKEN_OTHER.0, tables::TOKEN_OTHER.1);
                write_text(&mut writer, &token.text);
            }
        }
    }

    let header = ArtifactHeader::from(ArtifactKind::Tokens);
    let mut bytes = postcard::to_allocvec(&header).map_err(|_| ShareError::Unsupported)?;
    bytes.extend(writer.finish());
    Ok(bytes)
}

/// Read the next symbol of `symbols`, `None` at the end.
fn read_symbol<T: Copy>(
    reader: &mut BitReader,
    symbols: &HashMap<(u32, u8), T>,
) -> Result<Option<T>, ShareError> {
    let mut code = 0;
    for bits in 1..=32 {
        let Some(bit) = reader.read() else {
            // The last byte is filled with 1 bits, which are no code.
            return match bits <= 8 && code == (1 << (bits - 1)) - 1 {
                true => Ok(None),
                false => Err(ShareError::InvalidData("the code ends too early".into())),
            };
        };
        code = code << 1 | bit as u32;
        if let Some(symbol) = symbols.get(&(code, bits)) {
            return Ok(Some(*symbol));
        }
    }
    Err(ShareError::InvalidData("unknown code".into()))
}

/// Read a text until its end into `code`.
fn read_text(reader: &mut BitReader, code: &mut String) -> Result<(), ShareError> {
    loop {
        match read_symbol(reader, &TEXT_SYMBOLS)? {
            Some(TextSymbol::Char(c)) => code.push(c),
            Some(TextSymbol::End) => return Ok(()),
            Some(TextSymbol::Other) => {
                let c = reader
                    .read_bits(CODE_POINT_BITS)
                    .and_then(char::from_u32)
                    .ok_or_else(|| ShareError::InvalidData("invalid character".into()))?;
                code.push(c);
            }
            None => return Err(ShareError::InvalidData("a text has no end".into())),
        }
    }
}

/// The µcad code of serialized tokens, see [`serialize`].
///
/// Fails, if the bytes are no tokens of a compatible version.
pub fn deserialize(bytes: &[u8]) -> Result<String, ShareError> {
    if bytes.len() > MAX_SERIALIZED_BYTES {
        return Err(ShareError::TooLong(bytes.len()));
    }
    let (header, data): (ArtifactHeader, _) = postcard::take_from_bytes(bytes)
        .map_err(|err| ShareError::InvalidData(format!("no shared code: {err}")))?;
    if header.kind != ArtifactKind::Tokens {
        return Err(ShareError::InvalidData(format!(
            "an artifact of kind {} instead of tokens",
            header.kind
        )));
    }
    if !header.version.is_compatible() {
        return Err(ShareError::InvalidData(format!(
            "the code is shared by the incompatible version {}",
            header.version
        )));
    }

    let mut reader = BitReader::new(data);
    let mut code = String::new();
    while let Some(symbol) = read_symbol(&mut reader, &TOKEN_SYMBOLS)? {
        match symbol {
            TokenSymbol::Kind(Some(text)) => code.push_str(text),
            TokenSymbol::Kind(None) | TokenSymbol::Other => read_text(&mut reader, &mut code)?,
        }
    }
    Ok(code)
}

/// The link to the web viewer with `code`, whose [serialized](serialize) tokens are embedded
/// as URL-safe base64, e.g. `https://play.mucad.org/#wrUEAAYAOqNL82VFEihFboRpopz_` for
/// `Circle(r = 1mm);`.
///
/// Fails, if the code cannot be serialized.
pub fn link(code: &str) -> Result<String, ShareError> {
    Ok(format!(
        "{PLAY_URL}{}",
        URL_SAFE_NO_PAD.encode(serialize(code)?)
    ))
}

/// The link data of a link: after `#`, as `?code=`, in the path or the link is the data.
fn link_data(link: &str) -> &str {
    let link = link.trim();
    if let Some((_, data)) = link.split_once('#') {
        data
    } else if let Some((_, query)) = link.split_once('?') {
        query
            .split('&')
            .find_map(|parameter| parameter.strip_prefix("code="))
            .unwrap_or(query)
    } else {
        // Former links have the code in their path.
        link.strip_prefix(PLAY_URL.trim_end_matches('#'))
            .unwrap_or(link)
    }
}

/// The formatted code of a link, see [`link`].
///
/// The link is a complete link with the code after `#`, as `?code=` or in its path, or only
/// the link data, e.g. `wrUEAAYAOqNL82VFEihFboRpopz_`. Padding with `=` is optional.
///
/// The tokens are parsed and the code is formatted, code with errors is returned unformatted.
pub fn decode(link: &str) -> Result<String, ShareError> {
    let data = link_data(link);
    // A longer link contains more code than allowed, which is not decoded.
    if data.len() > MAX_SERIALIZED_BYTES.div_ceil(3) * 4 {
        return Err(ShareError::TooLong(data.len() / 4 * 3));
    }
    let engine = GeneralPurpose::new(
        &URL_SAFE,
        GeneralPurposeConfig::new().with_decode_padding_mode(DecodePaddingMode::Indifferent),
    );
    let bytes = engine
        .decode(data)
        .map_err(|err| ShareError::InvalidBase64(err.to_string()))?;
    let code = deserialize(&bytes)?;
    Ok(
        mucad_lang_format::format_code(&code, &mucad_lang_format::FormatConfig::default())
            .unwrap_or(code),
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The tokens of `code`.
    fn tokens(code: &str) -> Vec<Token<'_>> {
        mucad_lang_parse::lex(code)
            .map(|token| token.value)
            .collect()
    }

    /// The codes are complete prefix codes: no code is the start of another one, and the
    /// filled bits of the last byte are no token.
    #[test]
    fn complete_tables() {
        let kraft = |bits: &mut dyn Iterator<Item = u8>| -> f64 {
            bits.map(|bits| 0.5f64.powi(bits as i32)).sum()
        };
        let token_bits = || (tables::TOKENS.iter().map(|row| row.3)).chain([tables::TOKEN_OTHER.1]);
        assert_eq!(kraft(&mut token_bits()), 1.0);
        assert!(token_bits().max() > Some(8));
        let mut char_bits = (tables::CHARS.iter().map(|row| row.2))
            .chain([tables::TEXT_END.1, tables::TEXT_OTHER.1]);
        assert_eq!(kraft(&mut char_bits), 1.0);
    }

    /// The serialized code starts with the header of tokens, followed by fewer bytes than
    /// the code.
    #[test]
    fn serialize_code() {
        let code = "Circle(r = 1mm);";
        let bytes = serialize(code).expect("Serialized code");
        assert_eq!(bytes[..3], [0xc2, 0xb5, ArtifactKind::Tokens as u8]);
        assert!(bytes.len() - ArtifactHeader::SIZE < code.len());
        assert_eq!(deserialize(&bytes).as_deref(), Ok(code));
    }

    /// The tokens of code are deserialized into the code again, also tokens of unknown kinds,
    /// unknown characters and lexer errors.
    #[test]
    fn serialize_tokens() {
        for code in [
            "",
            "// µcad\nsketch S(r: Length) {\n    Circle(r);\n}\n",
            "x = false;",
            "s = \"a {x:05.2} b {{ \\n\";",
            "t = \"a\\\"{{}}\";",
            "/*  comment */ x = 1;",
            "x = 1 ~ 2 $ ☃;",
            "a = \"unclosed",
        ] {
            let bytes = serialize(code).expect(code);
            let deserialized = deserialize(&bytes).expect(code);
            assert_eq!(tokens(&deserialized), tokens(code), "{code}");
        }
    }

    /// The code of every µcad file of the examples and the standard library can be shared.
    #[test]
    fn serialize_files() {
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        for dir in ["examples", "crates/std/lib/std"] {
            for entry in std::fs::read_dir(root.join(dir)).expect("A directory") {
                let path = entry.expect("An entry").path();
                if path.extension().is_some_and(|ext| ext == "mu") {
                    let code = std::fs::read_to_string(&path).expect("A file");
                    if code.len() <= MAX_CODE_BYTES {
                        let bytes = serialize(&code).expect("Serialized code");
                        let deserialized = deserialize(&bytes).expect("Deserialized code");
                        assert_eq!(tokens(&deserialized), tokens(&code), "{path:?}");
                    }
                }
            }
        }
    }

    /// Code with more than 2048 bytes is too long for a link.
    #[test]
    fn link_too_long() {
        assert!(link(&"a".repeat(MAX_CODE_BYTES)).is_ok());
        // `µ` has two bytes.
        assert_eq!(
            link(&"µ".repeat(MAX_CODE_BYTES / 2 + 1)),
            Err(ShareError::TooLong(2050))
        );
    }

    /// The code of a link is decoded formatted, also from the fragment or query of a link.
    #[test]
    fn decode_link() {
        assert_eq!(
            link("Circle(r = 1mm);"),
            Ok("https://play.mucad.org/#wrUEAAYAOqNL82VFEihFboRpopz_".to_string())
        );
        let link = link("// µcad?>>\nCircle( r=1mm );\n").expect("A link");
        let data = link.strip_prefix(PLAY_URL).expect("The web viewer");
        assert!(
            data.chars()
                .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
        );

        let formatted = "// µcad?>>\nCircle(r = 1mm);";
        for link in [
            link.clone(),
            data.to_string(),
            format!("https://play.mucad.org/{data}"),
            format!("#{data}"),
            format!("https://play.mucad.org/?code={data}"),
            format!("?example=1&code={data}"),
            // With padding to a multiple of four characters.
            format!("{data}{}", "=".repeat((4 - data.len() % 4) % 4)),
        ] {
            assert_eq!(decode(&link).as_deref(), Ok(formatted), "{link}");
        }

        // Code with errors is not formatted.
        let link = super::link("Circle( r= ;").expect("A link");
        assert_eq!(decode(&link).as_deref(), Ok("Circle( r= ;"));
    }

    /// Invalid links fail.
    #[test]
    fn decode_invalid() {
        assert!(matches!(
            decode("#a+b/c"),
            Err(ShareError::InvalidBase64(_))
        ));
        // No header.
        let code = URL_SAFE_NO_PAD.encode("Circle(r = 1mm);");
        assert!(matches!(decode(&code), Err(ShareError::InvalidData(_))));
        // Another kind of artifact.
        let mut bytes = serialize("x = 1;").expect("Serialized code");
        bytes[2] = ArtifactKind::Ast as u8;
        assert!(matches!(
            deserialize(&bytes),
            Err(ShareError::InvalidData(_))
        ));
        // An incompatible version.
        bytes[2] = ArtifactKind::Tokens as u8;
        bytes[3] = 99;
        assert!(matches!(
            deserialize(&bytes),
            Err(ShareError::InvalidData(_))
        ));

        let too_long = URL_SAFE_NO_PAD.encode(vec![0; MAX_SERIALIZED_BYTES + 3]);
        assert!(matches!(decode(&too_long), Err(ShareError::TooLong(_))));
    }
}
